insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('career-aptitude-profile', 'Career Aptitude Profile', 'Maps your Brain Profile strengths and interests against career directions likely to suit how you think.', convert_from(decode('', 'base64'), 'UTF8'), 'compass', (select id from assessment_categories where key = 'self-discovery'), ('hybrid')::assessment_engine_type, ('easy')::assessment_difficulty, 15, 30, false, ('premium')::assessment_access, ('published')::assessment_status)
